mapper.select:
select
a.id,
a.proj_id projId,
b.proj_name projName,
b.proj_sponsor_user_id projSponsorUserId,
b.biz_dept_id bizDeptId,
b.client_id clientId,
a.template_id templateId,
b.biz_type bizType,
a.status,
a.flow_status flowStatus,
a.type,
a.archives_code archivesCode,
a.create_time createTime,
a.update_time updateTime
from archives_management a  left join proj_establish_base_info b
on a.proj_id = b.id

    and b.client_id = #{dto.clientId}
    and b.proj_name LIKE concat('%', #{dto.projName},'%')
    and b.biz_type = #{dto.bizType}
    and b.biz_dept_id = #{dto.bizDeptId}
    and b.proj_sponsor_user_id = #{dto.projSponsorUserId}
    and a.create_time  >=  #{dto.createTimeFrom}
    and a.create_time  <=  #{dto.createTimeTo}
    and a.update_time  >=  #{dto.updateTimeFrom}
    and a.update_time  <=  #{dto.updateTimeTo}
    and a.flow_status in("APPROVAL_PASS","SYS_APPROVAL_PASS")
    and a.id in
        
            #{item}
        
    

order by a.update_time desc
